import{_ as t,o as s,c as n,ah as a}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse('{"title":"Dépenses","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/caissier/depenses.md","filePath":"src/guide/caissier/depenses.md"}'),r={name:"guide/caissier/depenses.md"};function i(d,e,o,u,p,l){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="depenses" tabindex="-1">Dépenses <a class="header-anchor" href="#depenses" aria-label="Permalink to &quot;Dépenses&quot;">​</a></h1><p>La page <strong>Dépenses</strong> vous permet de soumettre une demande de dépense pour l&#39;établissement — par exemple un achat de matériel — et de suivre son état jusqu&#39;à la décision d&#39;un administrateur.</p><h2 id="enregistrer-une-depense" tabindex="-1">Enregistrer une dépense <a class="header-anchor" href="#enregistrer-une-depense" aria-label="Permalink to &quot;Enregistrer une dépense&quot;">​</a></h2><ol><li>Cliquez sur <strong>Nouvelle dépense</strong> en haut de la page <strong>Dépenses</strong>.</li><li>Choisissez le <strong>Site</strong> concerné par la dépense.</li><li>Indiquez le <strong>Montant</strong>.</li><li>Décrivez la dépense dans le champ <strong>Description</strong>.</li><li>Cliquez sur <strong>Soumettre la demande</strong>.</li></ol><p>Dès la soumission, les administrateurs de l&#39;établissement sont notifiés automatiquement qu&#39;une dépense attend leur décision — vous n&#39;avez rien d&#39;autre à faire.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Soumettre une dépense enregistre uniquement une demande de validation : cela ne débite aucun compte et n&#39;est pas relié à un dossier de facturation en particulier.</p></div><h2 id="suivre-l-etat-d-une-depense" tabindex="-1">Suivre l&#39;état d&#39;une dépense <a class="header-anchor" href="#suivre-l-etat-d-une-depense" aria-label="Permalink to &quot;Suivre l&#39;état d&#39;une dépense&quot;">​</a></h2><p>La liste de la page <strong>Dépenses</strong> affiche, pour chaque demande, le site, la description, le montant, qui l&#39;a demandée et son statut :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td>En attente</td><td>La demande n&#39;a pas encore été examinée par un administrateur</td></tr><tr><td>Approuvé</td><td>La dépense a été approuvée</td></tr><tr><td>Refusé</td><td>La dépense a été refusée, avec un motif consigné</td></tr></tbody></table><p>Vous pouvez filtrer cette liste par statut pour retrouver rapidement une dépense en attente ou déjà décidée. La décision elle-même (approuver ou refuser) est réservée aux comptes administrateur — vous ne verrez donc pas de bouton d&#39;action sur vos propres demandes ni sur celles de vos collègues.</p><p>Une fois une dépense <strong>approuvée</strong>, elle apparaît automatiquement comme décaissement dans l&#39;<a href="/guide/caissier/export-comptable.html">export comptable SYSCOHADA</a>.</p>',11)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
